          "ตรวจเบื้องต้นก่อนอัปโหลดขึ้นคลาวด์: แม้ทีมจะใช้เครื่องมือตรวจสอบบนคลาวด์เป็นด่านตรวจอย่างเป็นทางการ การตรวจบนเบราว์เซอร์ก่อนจะจับปัญหาที่เห็นได้ชัดได้โดยไม่ต้องอัปโหลด ช่วยลดทั้งค่าใช้จ่ายการใช้งานคลาวด์และจำนวนครั้งที่ต้องอัปโหลด",
