          "สองสัปดาห์ก่อนการส่งมอบตามหมุดหมายอย่างเป็นทางการทุกครั้ง: รันครบทั้งสามระดับ ตั้งเป้า Health Score ≥ 80 ก่อนตรวจ IDS เวลาสองสัปดาห์ทำให้แก้ไขได้โดยไม่ต้องเร่งรีบ แจ้งปัญหาแต่เนิ่น ๆ อย่าใช้เวลาเผื่อจนหมด",
