          "หลังอัปเกรดเวอร์ชันซอฟต์แวร์สร้างโมเดลหรือเปลี่ยนการตั้งค่าการส่งออก: สร้างค่าฐาน (baseline) ของความคงที่ของ GUID ขึ้นใหม่ โดยเปรียบเทียบไฟล์ที่ส่งออกสองครั้งติดกัน การอัปเกรด Revit หรือการเปลี่ยนการตั้งค่าการส่งออกอาจเปลี่ยนวิธีสร้าง GlobalId ไปโดยไม่มีใครรู้ตัว",
