            body: "แฟรกเมนต์เรขาคณิตที่แยกวิเคราะห์แล้วจะคงอยู่ใน OPFS หลังเซสชันแรก การโหลดซ้ำเร็วขึ้นราว 10 เท่า ไม่ต้องแยกวิเคราะห์ใหม่และไม่ต้องพึ่งเครือข่าย แคชเป็นข้อมูลส่วนตัวของต้นทางเบราว์เซอร์ และเซิร์ฟเวอร์ระยะไกลเข้าถึงไม่ได้",
